import {
  array,
  createTypeContext,
  declare,
  docComment,
  object,
  type JsonSchema,
  typeDeclaration,
} from "./render-defs.js";

const header = `// Generated by tooling/generate-types from definitions/runtime.schema.json.
// Do not edit by hand.
`;

const diagnosticCode = "DiagnosticCode";

/** A diagnostic code with what the runtime schema says about it. */
export interface CodeEntry {
  readonly code: string;
  readonly severity: string;
  readonly foundBy: string;
  readonly meaning: string;
}

/** The codes of `def`, in the schema's order. */
export function codeEntries(def: JsonSchema): readonly CodeEntry[] {
  const codes = array(def["x-lumen-codes"])
    .map(object)
    .map((entry) => {
      const { code, severity, foundBy, meaning } = entry;
      if (
        typeof code !== "string" ||
        typeof severity !== "string" ||
        typeof foundBy !== "string" ||
        typeof meaning !== "string"
      ) {
        throw new Error(`a \`DiagnosticCode\` entry lacks a field: ${JSON.stringify(entry)}`);
      }
      return { code, severity, foundBy, meaning };
    });
  if (codes.length === 0) throw new Error("`DiagnosticCode` lists no codes");
  return codes;
}

/**
 * \`DiagnosticCode\` lists the codes the engine knows and stays open to any string, because an
 * engine newer than the SDK can report a code it doesn't list.
 */
function renderDiagnosticCode(def: JsonSchema): string {
  const codes = codeEntries(def);
  const union = codes
    .map((entry) => `${docComment(entry.meaning, "  ")}  | ${JSON.stringify(entry.code)}`)
    .join("\n");
  return `${docComment(def.description, "")}export type ${diagnosticCode} =
${union}
  | (string & {});

/** Each diagnostic code with the severity of the diagnostics that carry it, where they are found (\`check\`, \`render\` or both) and what the code means, in Markdown. */
export const diagnosticCodes = [
${codes.map((entry) => `  { code: ${JSON.stringify(entry.code)}, severity: ${JSON.stringify(entry.severity)}, foundBy: ${JSON.stringify(entry.foundBy)}, meaning: ${JSON.stringify(entry.meaning)} },`).join("\n")}
] as const;`;
}

/** The contents of `generated/runtime.ts`: the types of the values the engine returns. */
export function renderRuntimeTypes(schema: JsonSchema): string {
  const defs = object(schema.$defs) as Record<string, JsonSchema>;
  const context = createTypeContext(defs, [], true);
  for (const [name, def] of Object.entries(defs)) {
    if (name !== diagnosticCode) declare(context, name, typeDeclaration(name, def, context, true));
  }
  const codeDef = defs[diagnosticCode];
  if (codeDef === undefined) throw new Error("the runtime schema has no `DiagnosticCode`");
  return `${header}
${renderDiagnosticCode(codeDef)}

${[...context.declarations.values()].join("\n\n")}
`;
}
